<?php
require_once __DIR__.'/../includes/bootstrap.php';require_role('Student');$sid=student_id($pdo);$msg='';$err='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$skill=(int)($_POST['skill_id']??0);if(val('action')==='remove'){$s=$pdo->prepare('DELETE FROM student_skill WHERE student_id=? AND skill_id=?');$s->execute([$sid,$skill]);$msg='Skill removed.';}else{$level=val('proficiency_level',30);if(!in_array($level,['Basic','Intermediate','Advanced','Expert'],true))$err='Invalid level.';else try{$s=$pdo->prepare('INSERT INTO student_skill(student_id,skill_id,proficiency_level) VALUES(?,?,?)');$s->execute([$sid,$skill,$level]);$msg='Skill added.';}catch(PDOException $e){$err='Skill already listed or invalid.';}}}
$s=$pdo->prepare('SELECT sk.skill_id,sk.skill_name,ss.proficiency_level FROM student_skill ss JOIN skill sk ON sk.skill_id=ss.skill_id WHERE ss.student_id=?');$s->execute([$sid]);$mine=$s->fetchAll();$all=$pdo->query('SELECT skill_id,skill_name FROM skill ORDER BY skill_name')->fetchAll();$b=($err?'<p class="error">'.e($err).'</p>':'').($msg?'<p class="ok">'.e($msg).'</p>':'').'<h2>My skills</h2><table><tr><th>Skill</th><th>Level</th><th>Action</th></tr>';
foreach($mine as $r)$b.='<tr><td>'.e($r['skill_name']).'</td><td>'.e($r['proficiency_level']).'</td><td><form method="post"><input type="hidden" name="csrf_token" value="'.e(csrf_token()).'"><input type="hidden" name="action" value="remove"><input type="hidden" name="skill_id" value="'.(int)$r['skill_id'].'"><button>Remove</button></form></td></tr>';
$b.='</table><form method="post"><input type="hidden" name="csrf_token" value="'.e(csrf_token()).'"><label>Skill<select name="skill_id">';foreach($all as $r)$b.='<option value="'.(int)$r['skill_id'].'">'.e($r['skill_name']).'</option>';$b.='</select></label><label>Proficiency<select name="proficiency_level"><option>Basic</option><option>Intermediate</option><option>Advanced</option><option>Expert</option></select></label><button>Add skill</button></form>';page('My skills',$b);
